/* ═══════════════════════════════════════════════════════════════════════════
   RELIEVE — el tinte hipsométrico de la carta SIGWX
   ───────────────────────────────────────────────────────────────────────────
   «Quiero que añadas un color más oscuro parecido a la foto, que marque la
   geografía del terreno» (7-sep-2026, con la carta del OFP al lado). En esa
   carta la tierra es casi blanca y encima lleva un lavado OCRE que sube con la
   ALTITUD: los Pirineos, la Meseta, Sierra Nevada y el Atlas se leen de un
   vistazo. Sin él la tierra es una silueta plana y el piloto no sitúa nada.

   ⚠ **Es ALTITUD DE VERDAD, no un sombreado dibujado a ojo.** Sale de las
   teselas «terrarium» de AWS Terrain Tiles —registro de datos abiertos de AWS:
   SRTM 3 arcsec, 3DEP y GMTED2010—, decodificadas con
   `elev = (R·256 + G + B/256) − 32768` y promediadas a la rejilla. Un
   relieve inventado sería el avión inventado otra vez, y encima de una carta es
   peor: el piloto lo lee como terreno.

   ── DOS REJILLAS, y la razón importa ──────────────────────────────────────
   `MUNDO` (1°, todo el planeta) y `FINO` (0,25°, la ventana EUR/MED que es
   donde se vuela). La fina sola dejaba un RECTÁNGULO con costura sobre Rusia y
   el Atlántico: dentro había relieve y fuera nada, y ese borde recto se lee
   como un dato. La del mundo va debajo y continúa fuera de la ventana; la fina
   se pinta encima donde la hay. No son dos copias de lo mismo —una cubre y la
   otra detalla—, así que NO es el caso `ES_AIRPORTS` / `ES_IATA`.

   Cada celda es un ESCALÓN (0-15) de `ESC`, no metros: dos por byte, en
   base64. Nivel 0 = mar o llanura y no se pinta.

   Lo genera `scripts/gen-relieve.js`. Si se amplía la ventana o cambia el
   paso, se vuelve a correr; no se edita a mano.
   ═══════════════════════════════════════════════════════════════════════════ */
(function (raiz, fabrica) {
  if (typeof module === 'object' && module.exports) module.exports = fabrica();
  else raiz.RELIEVE = fabrica();
})(typeof self !== 'undefined' ? self : this, function () {

  /* Los escalones, en metros. */
  var ESC = [0,100,200,300,450,600,800,1000,1250,1500,1800,2100,2500,2900,3400];

  /* Se descomprime bajo demanda: son cientos de miles de celdas y no hace falta
     pagarlas si el piloto no abre la carta. */
  function descomprime(b64, n) {
    var bin;
    if (typeof atob === 'function') {
      var s = atob(b64); bin = new Uint8Array(s.length);
      for (var i = 0; i < s.length; i++) bin[i] = s.charCodeAt(i);
    } else { bin = new Uint8Array(Buffer.from(b64, 'base64')); }
    var out = new Uint8Array(n);
    for (var k = 0; k < n; k++) out[k] = (k % 2 === 0) ? (bin[k >> 1] >> 4) : (bin[k >> 1] & 15);
    return out;
  }

  var MUNDO = {
    GW: 360, GH: 144, LO0: -180, LO1: 180, LA0: -60, LA1: 84, PASO: 1,
    b64: '', niv: null,
    niveles: function () { return this.niv || (this.niv = descomprime(this.b64, this.GW * this.GH)); }
  };

  var FINO = {
    GW: 380, GH: 220, LO0: -35, LO1: 60, LA0: 20, LA1: 75, PASO: 0.25,
    b64: '', niv: null,
    niveles: function () { return this.niv || (this.niv = descomprime(this.b64, this.GW * this.GH)); }
  };

  return {
    ESC: ESC,
    /* de menos a más detalle: se pintan EN ESTE ORDEN */
    capas: [MUNDO, FINO],
    MUNDO: MUNDO, FINO: FINO,
    /* metros aproximados de un escalón — para rotular, no para volar */
    metros: function (n) { return ESC[Math.max(0, Math.min(ESC.length - 1, n))]; }
  };
});
